25	
26	  let phase = $state<Phase>('enter');
27	  let code = $state('');
28	  let codeError = $state<string | undefined>(undefined);
29	  let preview = $state<AgentClaimPreview | null>(null);
30	  /** Terminal ceremony failures get their own explicit block, never a silent return. */
31	  let ceremonyError = $state<{ title: string; body: string } | null>(null);
32	
33	  let scopeDescriptions = $derived(preview ? describeScopes(preview.scopes) : []);
34	
35	  const REGISTRATION_TYPE_LABELS: Record<string, string> = {
36	    service_auth: 'Requested for your account by this server',
37	    identity_assertion: 'Vouched for by a trusted identity provider',
38	    anonymous: 'Registered directly by the agent',
39	  };
40	
41	  function errorCode(e: unknown): AgentsError['code'] | 'UNEXPECTED' {
42	    if (e && typeof e === 'object' && 'code' in e) return (e as AgentsError).code;
43	    return 'UNEXPECTED';
44	  }
45	
46	  function ceremonyFailure(codeName: string): { title: string; body: string } | null {
47	    switch (codeName) {
48	      case 'CODE_EXPIRED':
49	        return {
50	          title: 'This code has expired',
51	          body: 'Codes are only valid for a short window. Ask the agent to restart its connection request, then enter the new code.',
52	        };
53	      case 'ALREADY_CLAIMED':
54	        return {
55	          title: 'This code was already used',
56	          body: 'The request behind this code has already been approved. Check My agents to review what is connected.',
57	        };
58	      case 'ACCESS_DENIED':
59	        return {
60	          title: 'This request belongs to a different account',
61	          body: 'The agent asked to connect to another account on this server. Nothing was approved.',
62	        };
63	      case 'RATE_LIMITED':
64	        return {
65	          title: 'Too many attempts',
66	          body: 'Your server paused code checks for a few minutes. Wait, then try again.',
67	        };
68	      default:
69	        return null;
70	    }
71	  }
72	
73	  async function loadPreview() {
74	    codeError = undefined;
75	    ceremonyError = null;
76	    const trimmed = code.trim().toUpperCase();
77	    if (!trimmed) {
78	      codeError = 'Enter the code the agent showed you.';
79	      return;
80	    }
81	    phase = 'loading';
82	    try {
83	      preview = await previewAgentClaim(trimmed);
84	      code = trimmed;
85	      phase = 'review';
86	    } catch (e) {
87	      phase = 'enter';
88	      const c = errorCode(e);
89	      const terminal = ceremonyFailure(c);
90	      if (terminal) {
91	        ceremonyError = terminal;
92	      } else if (c === 'CODE_NOT_FOUND') {
93	        codeError = 'That code was not recognized. Check it and try again.';
94	      } else if (c === 'NOT_AUTHENTICATED') {
95	        codeError = 'Your wallet session has expired on this server.';
96	      } else {
97	        codeError = 'Could not reach your server. Check your connection and try again.';
98	      }
99	    }
100	  }
101	
102	  async function approve() {
103	    if (!preview) return;
104	    ceremonyError = null;
105	    phase = 'approving';
106	    try {
107	      // The biometric prompt is the authorization boundary: rejecting it aborts before any
108	      // network call, so cancel truly means nothing was granted.
109	      await authenticateBiometric('Approve this agent’s access to your identity');
110	    } catch {
111	      phase = 'review';
112	      return;
113	    }
114	    try {
115	      const confirmation = await confirmAgentClaim(code);
116	      phase = 'approved';
117	      // Give the sealed state a beat before handing control back.
118	      setTimeout(() => ondone(confirmation.registrationId), 1200);
119	    } catch (e) {
120	      phase = 'review';
121	      const terminal = ceremonyFailure(errorCode(e));
122	      ceremonyError = terminal ?? {
123	        title: 'Approval did not go through',
124	        body: 'Your server could not complete the approval. Nothing was granted — you can try again.',
125	      };
126	    }
127	  }
128	
129	  function deny() {
130	    // An explicit decision, not a silent back-swipe: denial simply never confirms the code,
131	    // and the pending request expires on the server.
132	    ceremonyError = null;
133	    preview = null;
134	    code = '';
135	    phase = 'enter';
